\set ON_ERROR_STOP on
select test.assert((select is_nullable='YES' and column_default is null from information_schema.columns where table_schema='public' and table_name='planned_account_transfers' and column_name='source_bill_id'),'new link nullable without row backfill');
select test.assert((select confrelid='public.bills'::regclass and confdeltype='a' and condeferrable and condeferred from pg_constraint where conname='planned_account_transfers_source_bill_fkey'),'source bill FK preserves references through whole-parent cascade timing');
select test.assert((select indisunique and indpred is not null from pg_index where indexrelid='public.planned_account_transfers_source_bill_uidx'::regclass),'one source can have only one durable conversion');
select test.assert((select count(*)=7 and bool_and(tgenabled='O') from pg_trigger where tgname in('planned_transfer_source_link_immutable','converted_bill_readonly','converted_bill_override_readonly','converted_bill_move_readonly','converted_bill_future_transaction_guard','converted_bill_future_reconciliation_guard','converted_bill_pending_match_guard')),'all seven scoped data guards enabled');
select test.assert(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in('convert_bill_to_planned_transfer','guard_planned_transfer_source_link','guard_converted_bill_history','guard_converted_bill_matching') and (not p.prosecdef or p.proconfig is distinct from array['search_path=""'])),'trusted private functions use empty search path');

select test.assert((select not prosecdef and proconfig=array['search_path=""'] from pg_proc where oid='private.bill_transfer_evidence_admitted(uuid,uuid,uuid)'::regprocedure) and not has_function_privilege('authenticated','private.bill_transfer_evidence_admitted(uuid,uuid,uuid)','EXECUTE'),'evidence admission helper is private invoker with no direct client grant');
